const heroRobLockupSvg = useMemo(() => {
  const laidOut = applyHeroSvgTextLayout(HERO_ROB_LOCKUP_SVG_BASE, activeSvgTextLayout);
  return nameStaggerActive ? hideHeroNameSvgGlyphs(laidOut) : laidOut;
}, [activeSvgTextLayout, nameStaggerActive]);

/** Staggered letter entrance — ROBBIE / MCLAUGHLIN. */
useEffect(() => {
  if (!auxVisible || reduceMotion) return;
  const root = heroSvgAlignRef.current;
  if (!root) return;

  const svgTexts = [
    ...root.querySelectorAll<SVGTextElement>(
      '[data-hero-part="robbie"], [data-hero-part="mclaughlin"]',
    ),
  ];
  if (svgTexts.length === 0) return;

  const chars: SVGTSpanElement[] = [];
  const savedFilters: { el: SVGTextElement; filter: string | null }[] = [];

  svgTexts.forEach((textEl) => {
    const content = textEl.textContent ?? "";
    if (!content) return;

    savedFilters.push({ el: textEl, filter: textEl.getAttribute("filter") });
    textEl.removeAttribute("filter");

    if (textEl.querySelector("tspan")) {
      chars.push(...textEl.querySelectorAll("tspan"));
      return;
    }
    textEl.textContent = "";
    for (const char of content) {
      const tspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
      tspan.textContent = char;
      textEl.appendChild(tspan);
      chars.push(tspan);
    }
  });

  if (chars.length === 0) {
    savedFilters.forEach(({ el, filter }) => {
      if (filter) el.setAttribute("filter", filter);
    });
    return;
  }

  const restoreFilters = () => {
    savedFilters.forEach(({ el, filter }) => {
      if (filter) el.setAttribute("filter", filter);
      else el.removeAttribute("filter");
    });
  };

  const tween = gsap.from(chars, {
    y: 50,
    opacity: 0,
    stagger: 0.03,
    duration: 0.6,
    ease: "back.out(1.7)",
    onComplete: restoreFilters,
  });

  return () => {
    tween.kill();
    gsap.set(chars, { clearProps: "transform,opacity" });
    restoreFilters();
  };
}, [auxVisible, reduceMotion, heroRobLockupSvg]);
